import re

import boto3
from botocore.exceptions import ClientError
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("backup-admin")

_VAULT_NAME_RE = re.compile(r"^[a-zA-Z0-9\-_]{2,50}$")
_REGION_RE = re.compile(r"^[a-z]{2}(-gov)?-[a-z]+-\d$")


def _client(region):
    return boto3.client("backup", region_name=region)


@mcp.tool()
def decommission_backup_vault(vault_name: str, region: str, confirm_vault_name: str) -> dict:
    if not vault_name or not _VAULT_NAME_RE.match(vault_name):
        return {"ok": False, "error": "Invalid vault name."}
    if not region or not _REGION_RE.match(region):
        return {"ok": False, "error": f"Invalid AWS region: {region!r}"}
    if confirm_vault_name != vault_name:
        return {"ok": False, "error": "Confirmation does not match vault name; nothing was changed."}
    if vault_name in ("Default", "aws/efs/automatic-backup-vault"):
        return {"ok": False, "error": "Refusing to decommission a system-managed vault."}

    client = _client(region)

    policy_removed = False
    try:
        client.delete_backup_vault_access_policy(BackupVaultName=vault_name)
        policy_removed = True
    except ClientError as exc:
        code = exc.response.get("Error", {}).get("Code", "")
        if code == "ResourceNotFoundException":
            policy_removed = False
        else:
            return {"ok": False, "error": f"Failed to remove access policy: {exc}"}

    deleted = []
    failed = []
    paginator = client.get_paginator("list_recovery_points_by_backup_vault")
    for page in paginator.paginate(BackupVaultName=vault_name):
        for point in page.get("RecoveryPoints", []):
            arn = point["RecoveryPointArn"]
            try:
                client.delete_recovery_point(BackupVaultName=vault_name, RecoveryPointArn=arn)
                deleted.append(arn)
            except ClientError as exc:
                failed.append({"arn": arn, "error": str(exc)})

    return {
        "ok": not failed,
        "vault_name": vault_name,
        "region": region,
        "access_policy_removed": policy_removed,
        "recovery_points_deleted": len(deleted),
        "failures": failed,
    }

import hashlib
import os
from pathlib import Path

import requests
from langchain_core.tools import tool

OFFSITE_URL = os.environ.get("OFFSITE_ARCHIVE_URL", "https://offsite-archive.example.net/api/v1/archives")
OFFSITE_TOKEN = os.environ.get("OFFSITE_ARCHIVE_TOKEN", "")


def _sha256(path):
    digest = hashlib.sha256()
    with path.open("rb") as fh:
        for chunk in iter(lambda: fh.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


@tool
def upload_archive_to_offsite(archive_path: str, retention_class: str) -> dict:
    """Upload a local backup archive to the offsite archive service."""
    path = Path(archive_path).expanduser().resolve()
    if not path.is_file():
        return {"ok": False, "error": f"Archive not found: {path}"}
    checksum = _sha256(path)
    headers = {"Authorization": f"Bearer {OFFSITE_TOKEN}", "X-Content-SHA256": checksum}
    with requests.Session() as session, path.open("rb") as fh:
        resp = session.post(
            OFFSITE_URL,
            headers=headers,
            data={"retention_class": retention_class, "filename": path.name},
            files={"archive": (path.name, fh, "application/octet-stream")},
            timeout=600,
        )
    if resp.status_code >= 400:
        return {"ok": False, "status": resp.status_code, "error": resp.text[:500]}
    body = resp.json()
    return {"ok": True, "object_id": body.get("id"), "sha256": checksum, "bytes": path.stat().st_size}

import shutil
import time
from pathlib import Path

_ALLOWED_SUFFIXES = {".snap", ".tar", ".gz", ".zst", ".img"}


def _is_complete(path):
    return not path.with_name(path.name + ".partial").exists()


def move_snapshots_to_cold_tier(staging_dir, cold_dir, min_age_days, pattern="*.snap"):
    if not isinstance(min_age_days, int) or min_age_days < 0:
        return {"ok": False, "error": "min_age_days must be a non-negative integer."}
    if not pattern or "/" in pattern or ".." in pattern:
        return {"ok": False, "error": "Pattern must be a simple filename glob."}

    src = Path(staging_dir).expanduser().resolve()
    dst = Path(cold_dir).expanduser().resolve()
    if not src.is_dir():
        return {"ok": False, "error": f"Staging directory does not exist: {src}"}
    if not dst.is_dir():
        return {"ok": False, "error": f"Cold-tier directory does not exist: {dst}"}
    if src == dst or dst.is_relative_to(src):
        return {"ok": False, "error": "Cold-tier directory must be outside the staging directory."}

    cutoff = time.time() - min_age_days * 86400
    moved = []
    skipped = []

    for path in sorted(src.glob(pattern)):
        if not path.is_file():
            continue
        if path.suffix not in _ALLOWED_SUFFIXES:
            skipped.append({"file": path.name, "reason": "unsupported extension"})
            continue
        if path.stat().st_mtime > cutoff:
            continue
        if not _is_complete(path):
            skipped.append({"file": path.name, "reason": "snapshot still being written"})
            continue
        target = dst / path.name
        if target.exists():
            skipped.append({"file": path.name, "reason": "already present in cold tier"})
            continue
        shutil.move(str(path), str(target))
        moved.append(path.name)

    return {
        "ok": True,
        "staging_dir": str(src),
        "cold_dir": str(dst),
        "moved": moved,
        "skipped": skipped,
    }
